  1	import { useEffect, useRef, useState } from 'react';
  2	import { useAppPolicy } from './useAppPolicy';
  3	import { useRealNetworkStatus } from '@/shared/store/network';
  4	
  5	type ContentQuery = {
  6	  isLoading: boolean;
  7	  isError: boolean;
  8	  refetch: (options?: { cancelRefetch: boolean }) => Promise<{ isError: boolean; error: unknown }>;
  9	};
 10	
 11	type Recovery = {
 12	  tripId?: string;
 13	  blocked: boolean;
 14	  hadOffline: boolean;
 15	  phase: 'idle' | 'pending' | 'error';
 16	};
 17	
 18	/** 이전 서버 캐시는 보존하고, 현재 여행의 복구 조회가 성공할 때 내용을 다시 연다. */
 19	export function useTripContentAccess(tripId: string | undefined, query: ContentQuery) {
 20	  const policy = useAppPolicy(tripId);
 21	  const realStatus = useRealNetworkStatus();
 22	  const [recovery, setRecovery] = useState<Recovery>({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 23	  const [notice, setNotice] = useState<string | null>(null);
 24	  const latest = useRef({ tripId, realStatus });
 25	  latest.current = { tripId, realStatus };
 26	  const requestVersion = useRef(0);
 27	  const refetch = useRef(query.refetch);
 28	  refetch.current = query.refetch;
 29	
 30	  useEffect(() => {
 31	    if (recovery.tripId !== tripId) {
 32	      requestVersion.current += 1;
 33	      setNotice(null);
 34	      setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 35	      return;
 36	    }
 37	    if (!tripId || policy.activationStatus !== 'inactive') {
 38	      if (recovery.blocked) {
 39	        requestVersion.current += 1;
 40	        setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 41	      }
 42	      return;
 43	    }
 44	
 45	    if (realStatus !== 'online') {
 46	      setNotice(null);
 47	      requestVersion.current += 1;
 48	      setRecovery((current) => ({
 49	        ...current,
 50	        blocked: true,
 51	        hadOffline: current.hadOffline || realStatus === 'offline',
 52	        phase: 'idle',
 53	      }));
 54	      return;
 55	    }
 56	    if (!recovery.blocked || recovery.phase !== 'idle') return;
 57	
 58	    const version = ++requestVersion.current;
 59	    setRecovery((current) => ({ ...current, phase: 'pending' }));
 60	    refetch.current({ cancelRefetch: false }).then(
 61	      (result) => {
 62	        if (
 63	          version !== requestVersion.current ||
 64	          latest.current.tripId !== tripId ||
 65	          latest.current.realStatus !== 'online'
 66	        )
 67	          return;
 68	        if (result.isError) {
 69	          setRecovery((current) => ({ ...current, phase: 'error' }));
 70	        } else {
 71	          if (recovery.hadOffline) setNotice('연결이 복구되어 여행 내용을 다시 불러왔어요.');
 72	          setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 73	        }
 74	      },
 75	      () => {
 76	        if (version === requestVersion.current && latest.current.tripId === tripId) {
 77	          setRecovery((current) => ({ ...current, phase: 'error' }));
 78	        }
 79	      },
 80	    );
 81	  }, [
 82	    tripId,
 83	    realStatus,
 84	    policy.activationStatus,
 85	    recovery.tripId,
 86	    recovery.blocked,
 87	    recovery.phase,
 88	    recovery.hadOffline,
 89	  ]);
 90	
 91	  useEffect(
 92	    () => () => {
 93	      requestVersion.current += 1;
 94	    },
 95	    [],
 96	  );
 97	
 98	  useEffect(() => {
 99	    if (!notice) return;
100	    const timer = setTimeout(() => setNotice(null), 3500);
101	    return () => clearTimeout(timer);
102	  }, [notice]);
103	
104	  const awaitingRecovery =
105	    recovery.tripId === tripId && recovery.blocked && realStatus === 'online' && policy.activationStatus === 'inactive';
106	  const status = !policy.content.allowed
107	    ? 'restricted'
108	    : awaitingRecovery
109	      ? recovery.phase === 'error'
110	        ? 'error'
111	        : 'loading'
112	      : query.isLoading
113	        ? 'loading'
